import{_ as a,c as t,o as n,ag as i}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"A08 — DynamoDB and RDS application integration","description":"","frontmatter":{},"headers":[],"relativePath":"practice/aws/associate-08.md","filePath":"practice/aws/associate-08.md"}'),o={name:"practice/aws/associate-08.md"};function r(s,e,l,d,c,p){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="a08-—-dynamodb-and-rds-application-integration" tabindex="-1">A08 — DynamoDB and RDS application integration <a class="header-anchor" href="#a08-—-dynamodb-and-rds-application-integration" aria-label="Permalink to “A08 — DynamoDB and RDS application integration”">​</a></h1><p><strong>Learner status: not started. All supplied tasks on this page are mandatory in this learning path</strong>, including items originally labelled optional or bonus. Repeating tasks still require the stated action or comparison; reuse earlier resources and code where suitable, and record the new evidence. Source optional labels describe the original course only.</p><p><strong>Read first:</strong> <a href="./../../aws/databases.html">databases</a>.</p><h2 id="a08-1-—-dynamodb-—-repeating-p04" tabindex="-1"><span class="hub-section-number">1 </span>A08.1 — DynamoDB — repeating P04 <a class="header-anchor" href="#a08-1-—-dynamodb-—-repeating-p04" aria-label="Permalink to “1 A08.1 — DynamoDB — repeating P04”">​</a></h2><ul><li>[ ] Create a table such as <code>User</code> with partition key <code>id</code>; inspect configuration and console sections.</li><li>[ ] Insert differently shaped records through console and CLI. Delete and recreate a disposable table through CLI.</li><li>[ ] Configure a global-table replica in another Region, create records and observe replication.</li><li>[ ] Write a Node.js SDK v3 CRUD script. Compare relevant libraries/tools and explain their roles without installing every listed library.</li><li>[ ] <strong>Promoted from optional:</strong> inspect the <code>feat/dynamodb-lab</code> course backend, connect it to the table and deploy it on EC2. Verify real API reads/writes. Use the supplied DynamoDB/EC2 PDF walkthrough as support.</li><li>[ ] <strong>Promoted from optional:</strong> define the table, stream and global-table replicas in a suitable CloudFormation resource; parameterize the requested name/Region values, deploy, inspect and remove the disposable stack. Validate the chosen resource&#39;s actual replica configuration rather than assuming a normal table gains replicas from a flag.</li><li>[ ] <strong>Promoted from optional; repeating infrastructure through CDK:</strong> investigate and demonstrate management of the relevant DynamoDB resources with CDK.</li></ul><h2 id="a08-2-—-rds-—-repeating-p08-with-ec2-deployment" tabindex="-1"><span class="hub-section-number">2 </span>A08.2 — RDS — repeating P08, with EC2 deployment <a class="header-anchor" href="#a08-2-—-rds-—-repeating-p08-with-ec2-deployment" aria-label="Permalink to “2 A08.2 — RDS — repeating P08, with EC2 deployment”">​</a></h2><ul><li>[ ] Provision an eligible PostgreSQL instance, or the source-permitted selected engine, in a suitable DB subnet group in the A07 VPC. Check actual account eligibility/cost rather than assume a free instance.</li><li>[ ] Connect with DBeaver/pgAdmin or an SSH tunnel through the bastion, depending on the selected topology. Create tables/data and run DDL, DML and CRUD operations.</li><li>[ ] Connect using <code>psql</code> from the bastion (for PostgreSQL), repeat CRUD and investigate CLI/SDK RDS management operations. Distinguish managing an RDS instance from querying SQL through a database driver.</li><li>[ ] Compare relevant ORMs and inspect the supplied application example. <strong>Promoted from optional:</strong> connect/deploy the database-backed application on EC2 and verify persistence, using the RDS/EC2 PDF guide as support.</li><li>[ ] <strong>Promoted from optional:</strong> create RDS Proxy for a compatible selected database configuration, connect through it and compare the connection path with direct access.</li><li>[ ] <strong>Promoted from optional; repeating infrastructure through CDK:</strong> investigate and demonstrate RDS resource management through CDK.</li><li>[ ] Stop eligible instances only for short idle periods under current service rules; remove unused resources, snapshots and both global-table Regions when the learning dependency is finished.</li></ul><h2 id="completion-evidence" tabindex="-1"><span class="hub-section-number">3 </span>Completion evidence <a class="header-anchor" href="#completion-evidence" aria-label="Permalink to “3 Completion evidence”">​</a></h2><ul><li>[ ] Record observed results for every section, including all promoted extensions.</li><li>[ ] Retain configuration/code, successful and denied/failing cases where specified, and actual cleanup state.</li><li>[ ] Link earlier evidence for repeating work and add the new interface/behavior comparison.</li></ul><p>Use the <a href="./#evidence-for-every-required-module">shared evidence rules</a>; never claim screenshots or sample code complete independent work.</p>',10)])])}const g=a(o,[["render",r]]);export{u as __pageData,g as default};
